package com.tastenest.servlet;
import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*; import com.tastenest.util.DB;
@WebServlet("/menu")
public class MenuServlet extends HttpServlet { protected void doGet(HttpServletRequest req,HttpServletResponse res)throws IOException {res.setContentType("application/json"); try{DB.init(); try(Connection c=DB.get();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT * FROM menu_items ORDER BY id")){StringBuilder b=new StringBuilder("[");boolean first=true;while(r.next()){if(!first)b.append(',');first=false;b.append("{\"id\":"+r.getInt("id")+",\"name\":\""+esc(r.getString("name"))+"\",\"description\":\""+esc(r.getString("description"))+"\",\"price\":"+r.getBigDecimal("price")+",\"category\":\""+esc(r.getString("category"))+"\",\"available\":"+r.getBoolean("available")+"}");}b.append(']');res.getWriter().print(b);}}catch(Exception e){res.setStatus(500);res.getWriter().print("{\"error\":\"Database not connected. Start MySQL in XAMPP.\"}");}} private String esc(String x){return x==null?"":x.replace("\\","\\\\").replace("\"","\\\"");}}
